package local.v60.player;

import android.content.res.ColorStateList;
import android.widget.*;
import java.util.function.*;

/** Advanced controls use the same compact native surfaces as the output page. */
final class YinDspControls {
    private final MainActivity a;private final YinUi u;private final AudioSettings s;private final DspSettings d;private final Runnable save,redraw;
    YinDspControls(MainActivity a,AudioSettings s,Runnable save,Runnable redraw){this.a=a;u=new YinUi(a);this.s=s;d=s.dsp;this.save=save;this.redraw=redraw;}
    private void toggle(LinearLayout p,String name,boolean value,Consumer<Boolean> set){Switch v=new Switch(a);u.tint(v);v.setText(name);v.setTextColor(YinUi.INK);v.setTextSize(14);v.setPadding(0,u.d(8),0,u.d(8));v.setChecked(value);v.setOnCheckedChangeListener((b,on)->{set.accept(on);save.run();redraw.run();});p.addView(v);}
    private void slider(LinearLayout p,String name,int initial,int min,int max,IntConsumer set,IntFunction<String> display){TextView label=u.text(name+" · "+display.apply(initial),12,YinUi.MUTED);p.addView(label);SeekBar bar=new SeekBar(a);bar.setMax(max-min);bar.setProgress(initial-min);bar.setContentDescription(name);bar.setProgressTintList(ColorStateList.valueOf(YinUi.ACCENT));bar.setThumbTintList(ColorStateList.valueOf(YinUi.ACCENT));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int v,boolean user){if(user){set.accept(v+min);label.setText(name+" · "+display.apply(v+min));}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){save.run();redraw.run();}});p.addView(bar,new LinearLayout.LayoutParams(-1,u.d(44)));}
    void eq(LinearLayout parent,int selected,IntConsumer select){
        LinearLayout p=u.card(parent,"","EQ paramétrico y corrección");toggle(p,"Editar frecuencia y anchura",d.parametric,v->{if(v&&!d.parametricEdited){for(int i=0;i<10;i++)d.gain[i]=s.gains[i];d.parametricEdited=true;}d.parametric=v;});
        if(d.parametric){u.gap(p,8);for(int first=0;first<10;first+=5){LinearLayout row=u.row();for(int col=0;col<5;col++){final int band=first+col;Button b=u.button(String.valueOf(band+1),()->select.accept(band));b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(0,u.d(6),0,u.d(6));b.setContentDescription("Editar banda "+(band+1));if(band==selected){b.setTextColor(YinUi.BG);b.setBackground(u.shape(YinUi.ACCENT,16));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,u.d(42),1);lp.setMargins(u.d(3),u.d(3),u.d(3),u.d(3));row.addView(b,lp);}p.addView(row);}u.gap(p,10);
            int f=(int)Math.round(Math.log(d.hz[selected]/20.0)/Math.log(1000)*1000);
            slider(p,"Frecuencia de banda "+(selected+1),f,0,1000,v->d.hz[selected]=(int)Math.round(20*Math.pow(1000,v/1000.0)),v->Math.round(20*Math.pow(1000,v/1000.0))+" Hz");
            slider(p,"Ganancia",(int)Math.round(d.gain[selected]*10),-120,120,v->{d.gain[selected]=v/10.0;s.gains[selected]=(int)Math.round(v/10.0);},v->String.format(java.util.Locale.ROOT,"%.1f dB",v/10.0));
            slider(p,"Anchura Q",(int)Math.round(d.q[selected]*100),10,1200,v->d.q[selected]=v/100.0,v->String.format(java.util.Locale.ROOT,"%.2f",v/100.0));
            LinearLayout channel=u.row();String[] channelNames={"Izquierdo","Derecho","Ambos"};for(int i=0;i<3;i++){final int c=i;Button b=u.button(channelNames[i],()->{d.channel[selected]=c;save.run();redraw.run();});b.setTextSize(11);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(u.d(3),u.d(8),u.d(3),u.d(8));if(d.channel[selected]==c){b.setTextColor(YinUi.BG);b.setBackground(u.shape(YinUi.ACCENT,14));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(u.d(3),u.d(3),u.d(3),u.d(3));channel.addView(b,lp);}p.addView(channel);u.gap(p,4);
            LinearLayout kinds=u.row();String[] names={"Campana","Graves","Agudos"};for(int i=0;i<3;i++){final int kind=i;Button b=u.button(names[i],()->{d.type[selected]=kind;save.run();redraw.run();});b.setTextSize(11);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(u.d(4),u.d(10),u.d(4),u.d(10));if(d.type[selected]==i){b.setTextColor(YinUi.BG);b.setBackground(u.shape(YinUi.ACCENT,14));}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(u.d(3),u.d(4),u.d(3),u.d(4));kinds.addView(b,lp);}p.addView(kinds);
        }
        u.gap(p,12);p.addView(u.button("Importar corrección AutoEQ / APO",()->a.importEffect(s.profile,s.storageKey,false)));u.gap(p,8);p.addView(u.text("Texto local: hasta 10 filtros PK/LS/HS. Ajuste fino de ganancia a 0,1 dB y Q a 0,01; la importación conserva los decimales.",11,YinUi.MUTED));
        LinearLayout ir=u.card(parent,"","Convolver · impulsos IR");ir.addView(u.text(d.irName.isEmpty()?"No hay un impulso cargado":d.irName,13,YinUi.MUTED));
        if(!d.irFile.isEmpty())toggle(ir,"Aplicar impulso",d.convolver,v->d.convolver=v);
        ir.addView(u.button(d.irFile.isEmpty()?"Cargar WAV / IRS":"Cambiar impulso",()->a.importEffect(s.profile,s.storageKey,true)));
        if(d.convolver){slider(ir,"Mezcla del impulso",d.irMix,0,100,v->d.irMix=v,v->v+" %");slider(ir,"Ganancia del impulso",d.irGain,-24,0,v->d.irGain=v,v->v+" dB");}
        ir.addView(u.text("IR mono/estéreo en formato WAV, hasta 2 segundos y 16 MB. Se adapta a la frecuencia de salida. A 384 kHz aumenta el uso de CPU.",11,YinUi.MUTED));
    }
    void dynamics(LinearLayout parent){
        LinearLayout bass=u.card(parent,"","Graves dinámicos");toggle(bass,"Realzar graves suaves",d.bass,v->d.bass=v);if(d.bass){slider(bass,"Refuerzo máximo",d.bassGain,1,6,v->d.bassGain=v,v->v+" dB");slider(bass,"Zona de graves",d.bassHz,40,160,v->d.bassHz=v,v->v+" Hz");}
        LinearLayout comp=u.card(parent,"","Compresor");toggle(comp,"Controlar diferencias de volumen",d.compressor,v->d.compressor=v);if(d.compressor){slider(comp,"Umbral",d.threshold,-40,-6,v->d.threshold=v,v->v+" dBFS");slider(comp,"Relación",d.ratio,1,10,v->d.ratio=v,v->v+":1");slider(comp,"Ataque",d.attack,1,100,v->d.attack=v,v->v+" ms");slider(comp,"Recuperación",d.release,40,1000,v->d.release=v,v->v+" ms");}
        LinearLayout protect=u.card(parent,"","Control de picos y volumen");toggle(protect,"Limitar la salida digital",d.protection,v->d.protection=v);if(d.protection){slider(protect,"Pico máximo",d.ceiling,-18,-1,v->d.ceiling=v,v->v+" dBFS");slider(protect,"Reducción de volumen",d.outputTrim,-18,0,v->d.outputTrim=v,v->v+" dB");}protect.addView(u.text("Reduce picos y nivel digital. No mide dB acústicos ni garantiza un volumen seguro para el oído.",11,YinUi.MUTED));
    }
    void space(LinearLayout parent){
        if(s.profile.equals("speaker")){LinearLayout p=u.card(parent,"","Efectos para auriculares");p.addView(u.text("Crossfeed, surround diferencial y antifatiga se aplican en AUX, Bluetooth o USB, no en el altavoz integrado.",13,YinUi.MUTED));return;}
        LinearLayout cross=u.card(parent,"","Crossfeed");toggle(cross,"Mezclar suavemente ambos canales",d.crossfeed,v->d.crossfeed=v);if(d.crossfeed)slider(cross,"Intensidad",d.crossfeedAmount,5,60,v->d.crossfeedAmount=v,v->v+" %");cross.addView(u.text("Reduce la separación extrema entre oídos. Es un enfoque de comodidad espacial, inspirado en efectos como Cure; no una copia de su algoritmo.",11,YinUi.MUTED));
        LinearLayout surround=u.card(parent,"","Surround diferencial");toggle(surround,"Ampliar el espacio estéreo",d.surround,v->d.surround=v);if(d.surround){slider(surround,"Retardo diferencial",d.delay,1,25,v->d.delay=v,v->v+" ms");slider(surround,"Intensidad espacial",d.surroundAmount,5,60,v->d.surroundAmount=v,v->v+" %");}surround.addView(u.text("Retardo estéreo por efecto Haas, inspirado en el concepto de Differential Surround. Solo actúa en audio estéreo.",11,YinUi.MUTED));
        LinearLayout comfort=u.card(parent,"","Antifatiga · agudos suaves");toggle(comfort,"Suavizar presencia y brillo",d.comfort,v->d.comfort=v);if(d.comfort){slider(comfort,"Reducción de aspereza",d.comfortAmount,1,6,v->d.comfortAmount=v,v->"−"+v+" dB");slider(comfort,"Zona de presencia",d.comfortHz,2000,6000,v->d.comfortHz=v,v->v+" Hz");}comfort.addView(u.text("Atenuación suave de presencia y agudos. Ajuste de comodidad; no identifica frecuencias universalmente dañinas ni sustituye controlar volumen y tiempo.",11,YinUi.MUTED));
    }
}
